+		F("  return %s;\n", vec4_color_variable);
+		break;
+	case GLSL_VULKAN:
+	default:  // OpenGL
+		F("  %s = %s;\n", lang_.fragColor0, vec4_color_variable);
+		break;
+	}
+	C("}\n");
+}
