+	std::vector<std::string> cheatList, formattedList;
+	cheatEngine2 = new CWCheatEngine();
+	cheatList = cheatEngine2->GetCodesList();
+
+	for (size_t i = 0; i < cheatList.size(); i++) {
+		if (cheatList[i].substr(0, 3) == "_C1") {
