+static const uint32_t FLIvalues[32] = {
+	0xBF800000, // -1.0
+	0x00800000, // FLT_MIN (note: a bit special)
+	0x37800000, // pow(2, -16)
+	0x38000000, // pow(2, -15)
+	0x3B800000, // pow(2, -8)
+	0x3C000000, // pow(2, -7)
+	0x3D800000, // 0.0625
