+	uint32_t end = start + ((bytes + 1023) >> 10);
+	bool result = false;
+	for (uint32_t i = start; i < end; ++i) {
+		if (vramDirty_[i] & (uint8_t)value) {
+			result = true;
+			vramDirty_[i] &= ~(uint8_t)value;
+		}
+	}
+
+	lastDirtyAddr_ = 0;
+	lastDirtySize_ = 0;
+
